        board = chess.Board()
        idx = 2
    elif tokens[1] == 'fen':
        # fen string up to before 'moves' or end
        try:
            moves_idx = tokens.index('moves')
            fen_tokens = tokens[2:moves_idx]
            idx = moves_idx + 1
        except ValueError:
            fen_tokens = tokens[2:]
            idx = len(tokens)
        fen = ' '.join(fen_tokens)
        board = chess.Board(fen)
