        board = chess.Board()
        idx = 1  # ???
    # apply moves if any
    if idx < len(tokens):
        for m in tokens[idx:]:
            try:
                board.push_uci(m)
            except Exception:
                try:
                    board.push(chess.Move.from_uci(m))
